	@Test
	void structuralScopeRefusesAnIndexWhenItsInitialOwnersDoNotFitTheLedger() throws Exception {
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(1024L, 1024L);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		try (var fixture = new NativeRowTermDomainExecutionTest.Fixture("ordinal", "left", "right", "result")) {
			LmdbNativeCompiledBoolean filter = fixture.countedFilter(new FunctionCall(FN.CONTAINS.stringValue(),
					Var.of("left"), new ValueConstant(SimpleValueFactory.getInstance().createLiteral("α"))));
			RowState row = fixture.row();
			int accepted = 0;
			try (RowCursor cursor = new FilterCursor(
					SlotPlan.values(fixture.repeatedRows().toArray(ValuesRow[]::new)).open(row), filter, row)) {
				while (row.advance(cursor)) {
					accepted++;
				}
			}
			assertThat(accepted).isEqualTo(64);
			assertThat(fixture.evaluations).hasValue(128);
			// With 8-byte references the structural scope/key/map/claim owners require at least1072 bytes,
			// including the initial Object[64] identity-index array. A1024-byte ledger cannot admit that index.
			assertThat(manager.usedBytes()).as("a refused structural index must not retain a partial cache claim")
					.isZero();
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
		}
		assertThat(manager.usedBytes()).isZero();
	}

	@Test
	void replacementIndexCleanupPreservesTheOriginalIoFailureAndEveryOwnedRelease() throws Exception {
		String previousBudget = System.getProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
		LmdbQueryMemoryManager previous = LmdbNativeHashJoin.queryMemoryOverride;
		LmdbQueryMemoryManager manager = LmdbQueryMemoryManager.createForTesting(64L << 10, 64L << 10);
		LmdbNativeHashJoin.queryMemoryOverride = manager;
		System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, "4096");
		try {
			long created = NativeExpressionDomain.SPILL_FILES_CREATED.get();
			long deleted = NativeExpressionDomain.SPILL_FILES_DELETED.get();
			try (var fixture = new NativeRowTermDomainExecutionTest.Fixture("ordinal", "text", "result")) {
				assertThat(drainDistinctInputs(fixture, 70)).isEqualTo(70);
				assertThat(fixture.evaluations).hasValue(70);
			}
			assertThat(NativeExpressionDomain.SPILL_FILES_CREATED.get() - created)
					.as("the positive control must really replace an index after its first48 entries")
					.isGreaterThanOrEqualTo(3L);
			assertThat(NativeExpressionDomain.SPILL_FILES_DELETED.get() - deleted)
					.isEqualTo(NativeExpressionDomain.SPILL_FILES_CREATED.get() - created);
			assertThat(manager.usedBytes()).isZero();

			UncheckedIOException original = new UncheckedIOException("replacement index opening failed",
					new IOException("original controlled I/O failure"));
			IOException cleanup = new IOException("replacement index deletion failed");
			Path failedReplacement = mock(Path.class);
			when(failedReplacement.toFile()).thenThrow(original);
			List<Path> physicalFiles = new ArrayList<>();
			List<Path> setupFiles = new ArrayList<>();
			AtomicInteger indexCreations = new AtomicInteger();
			try (MockedStatic<Files> files = mockStatic(Files.class, call -> {
				if (call.getMethod().getName().equals("deleteIfExists")
						&& call.getArgument(0) == failedReplacement) {
					return false;
				}
				Object result = call.callRealMethod();
				if (call.getMethod().getName().equals("createTempFile") && result instanceof Path path) {
					// CALLS_REAL_METHODS-style stubbing itself may invoke creation. Own those setup files explicitly.
					setupFiles.add(path);
				}
				return result;
			})) {
				files.when(() -> Files.createTempFile("rdf4j-lmdb-expression-payload-", ".spill"))
						.thenAnswer(call -> {
							Path path = (Path) call.callRealMethod();
							physicalFiles.add(path);
							return path;
						});
				files.when(() -> Files.createTempFile("rdf4j-lmdb-expression-index-", ".spill"))
						.thenAnswer(call -> {
							if (indexCreations.incrementAndGet() == 2) {
								return failedReplacement;
							}
							Path path = (Path) call.callRealMethod();
							physicalFiles.add(path);
							return path;
						});
				files.when(() -> Files.deleteIfExists(failedReplacement)).thenThrow(cleanup);
				Throwable observed;
				try (var fixture = new NativeRowTermDomainExecutionTest.Fixture("ordinal", "text", "result")) {
					observed = catchThrowable(() -> drainDistinctInputs(fixture, 70));
					assertThat(fixture.evaluations).as("fault injection starts at the actual49th distinct tuple")
							.hasValue(49);
				}
				assertThat(indexCreations).hasValue(2);
				assertThat(physicalFiles).hasSize(2);
				for (Path path : physicalFiles) {
					files.verify(() -> Files.deleteIfExists(path), times(1));
					assertThat(Files.exists(path)).isFalse();
				}
				files.verify(() -> Files.deleteIfExists(failedReplacement), times(1));
				assertThat(manager.usedBytes()).isZero();
				assertThat(observed).as("replacement cleanup must retain the original per-occurrence I/O failure")
						.isSameAs(original);
				assertThat(observed.getSuppressed()).anyMatch(problem -> problem == cleanup
						|| problem instanceof UncheckedIOException io && io.getCause() == cleanup);
			} finally {
				for (Path path : setupFiles) {
					Files.deleteIfExists(path);
				}
			}
		} finally {
			LmdbNativeHashJoin.queryMemoryOverride = previous;
			if (previousBudget == null) {
				System.clearProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY);
			} else {
				System.setProperty(NativeCountGroupStore.MAX_BYTES_PROPERTY, previousBudget);
			}
		}
	}

	private static int drainDistinctInputs(NativeRowTermDomainExecutionTest.Fixture fixture, int count)
			throws Exception {
		List<ValuesRow> values = new ArrayList<>();
		for (int ordinal = 0; ordinal < count; ordinal++) {
			values.add(fixture.values(ordinal, "value-" + ordinal));
		}
		CopyBinding copy = fixture.countedCopy(new FunctionCall(FN.STRING_LENGTH.stringValue(), Var.of("text")), 2);
		RowState row = fixture.row();
		int emitted = 0;
		try (RowCursor cursor = new ExtensionCursor(SlotPlan.values(values.toArray(ValuesRow[]::new)).open(row),
				new CopyBinding[] { copy }, row)) {
			while (row.advance(cursor)) {
				assertThat(((Literal) fixture.source.lazyValue(row.id(0))).intValue()).isEqualTo(emitted);
				assertThat(((Literal) fixture.source.lazyValue(row.id(2))).intValue())
						.isEqualTo(("value-" + emitted).length());
				emitted++;
			}
		}
		assertThat(row.boundMask()).isZero();
		return emitted;
	}
